import{_ as d,C as s,o as g,c as i,a3 as a,j as t,E as o,a as n,w as h}from"./chunks/framework.DSv4yICS.js";const c="/versions/v0.19.33/screens/snapshots/arrange_playback.png",p="/versions/v0.19.33/screens/snapshots/arrange.png",u="/versions/v0.19.33/screens/snapshots/arrange_hold_select.png",E=JSON.parse('{"title":"Arrange","description":"","frontmatter":{},"headers":[],"relativePath":"snapshots/lanes.md","filePath":"snapshots/lanes.md"}'),m={name:"snapshots/lanes.md"},w={tabindex:"0"};function b(f,e,S,k,T,y){const r=s("C"),l=s("ManualRelated");return g(),i("div",null,[e[14]||(e[14]=a('<h1 id="arrange" tabindex="-1">Arrange <a class="header-anchor" href="#arrange" aria-label="Permalink to &quot;Arrange&quot;">​</a></h1><p>Arrange is the <strong>song grid</strong> for stored snapshots: <strong>4–256 rows</strong> of time (default <strong>16</strong>) × 10 columns (Knobs, S32 LFOs, Rack 1–8). When the playhead lands on a row it recalls every occupied cell in that row (a scene). Empty cells are <strong>rest</strong> (<code>--</code>) and skip that bank. It is <strong>not</strong> a Step Seq MIDI device and does not sit in a rack.</p><p>Open <strong>ARRANGE</strong> from <a href="./../navigation/main-menu">Main Menu</a> — it is the <strong>first</strong> item, above Racks. The hub opens on the Knobs column. Rack, LFO, and 4×8 nested menus do <strong>not</strong> have an Arrange shortcut.</p><p>The header title is <strong>ARRANGE</strong> (no timeline icon). Folder tabs <strong>SONG</strong> and a <strong>pencil</strong> sit left of the BPM band (never in it). The selected tab fills the header to the top, with a thin shadow on both sides; the idle tab has no stroke. The pencil is SETTINGS — the header never writes SETTINGS or SET. Two small filled squares between the tabs and the BPM mark <strong>Select + Back</strong>. Hold Select for a moment on <strong>SONG</strong> and those squares become a circle and square (hold Select and turn to pick a column). A tap that never reached that hold still opens the cell picker; letting go after the column corners are showing does not. The gray header line runs the full width, including under the BPM, and meets the tab corners with a tiny radius. The BPM metronome in the header <strong>animates</strong> with the project clock.</p><h2 id="song-tab" tabindex="-1">SONG tab <a class="header-anchor" href="#song-tab" aria-label="Permalink to &quot;SONG tab&quot;">​</a></h2><p>All <strong>ten</strong> columns are on one page: <strong>K L R1 R2 R3 R4 R5 R6 R7 R8</strong>. Five song rows are visible; longer songs scroll so the focused cell stays in view. Occupied cells show two-digit slot ids <strong>01–32</strong>. Rest cells show <code>--</code>. Row numbers on the left are three digits <strong>001–256</strong>. The cursor is <strong>tiny L-corners</strong> at the focused cell (and a full-column handle while you hold Select + turn). Unselected columns <strong>dim</strong> during that column hold. Idle row numbers are dimmer than the playing row. The playing row is <strong>brighter ink</strong> (occupied cells go white, rests stay a dimmer gray). There is no playhead bar in the gutter and no line under the column headers. A <strong>QUEUE-armed</strong> row <strong>pulses</strong> (row number and cell labels) until it fires or you cancel — idle rows stay still. A morphing bank’s column header is <code>K*</code> / <code>L*</code> / <code>R1*</code>…<code>R8*</code>. Column names are a <strong>legend</strong> (not an encoder stop).</p>',6)),t("table",w,[e[12]||(e[12]=t("thead",null,[t("tr",null,[t("th",null,"Control"),t("th",null,"SONG")])],-1)),t("tbody",null,[e[9]||(e[9]=t("tr",null,[t("td",null,"Encoder"),t("td",null,"Move the song row (001–LENGTH, clamped)")],-1)),e[10]||(e[10]=t("tr",null,[t("td",null,"Hold Select + encoder"),t("td",null,"Move columns (K … R8); stops at the ends, does not wrap. After a short hold the header mark becomes a circle and square, and the column corners appear even before you turn. Letting go after that hold does not open the cell picker.")],-1)),t("tr",null,[t("td",null,[o(r,{action:"select"}),e[0]||(e[0]=n()),e[1]||(e[1]=t("strong",null,"Select",-1))]),e[2]||(e[2]=t("td",null,[n("Open a cell picker (REST + occupied slots). Dark panel, side-menu gray border, selected line inverted (white on black). Encoder does not wrap. Back cancels. Select applies. After the "),t("strong",null,"pencil"),n(" → "),t("strong",null,"SONG"),n(", the first Select still opens the picker.")],-1))]),t("tr",null,[t("td",null,[o(r,{action:"back-select"}),e[3]||(e[3]=n()),e[4]||(e[4]=t("strong",null,"Select + Back",-1))]),e[5]||(e[5]=t("td",null,[n("Switch to the "),t("strong",null,"pencil"),n(" tab (not zoom; not Select long-press)")],-1))]),e[11]||(e[11]=t("tr",null,[t("td",null,"Encoder click"),t("td",null,"Clock Start/Stop")],-1)),t("tr",null,[t("td",null,[o(r,{action:"back"}),e[6]||(e[6]=n()),e[7]||(e[7]=t("strong",null,"Back",-1))]),e[8]||(e[8]=t("td",null,"Leave Arrange",-1))])])]),e[15]||(e[15]=a('<p>The playing row follows the project clock. Start transport from the encoder button (Clock Start/Stop) or Clock Settings.</p><h2 id="pencil-tab" tabindex="-1">Pencil tab <a class="header-anchor" href="#pencil-tab" aria-label="Permalink to &quot;Pencil tab&quot;">​</a></h2><p>A full-width list with the same <strong>13 px</strong> rows as other parameter lists (four visible; encoder scrolls): <strong>ARRANGE</strong>, <strong>RATE</strong>, <strong>FADE TIME</strong>, <strong>REPEAT</strong>, <strong>LENGTH</strong>, <strong>JUMP TO</strong>, <strong>QUEUE</strong>. Encoder moves between rows. Selected rows are <strong>white text</strong> on the canvas, like menus, with the same tiny L-corners as SONG (Gray6). <strong>Hold Select</strong> marks the row Gray8 (no filled band). Short <strong>Select</strong> on <strong>RATE</strong>, <strong>FADE TIME</strong>, <strong>REPEAT</strong>, or <strong>LENGTH</strong> latches sticky edit (nested corners; turn without holding Select). Tap Select again to keep the value; <strong>Back</strong> restores it — including the <strong>SONG</strong> / <strong>JUMP TO</strong> row if you had shortened <strong>LENGTH</strong>. Turn the encoder while holding Select to edit ARRANGE / RATE / FADE TIME / REPEAT / <strong>LENGTH</strong>, or to pick the SONG-focused row on <strong>JUMP TO</strong> (001–LENGTH, the same cursor as SONG). <strong>ARRANGE</strong> ON/OFF, <strong>REPEAT</strong>, <strong>RATE</strong>, <strong>FADE TIME</strong>, and <strong>LENGTH</strong> stop at the ends — they do not wrap. Hold Select on <strong>QUEUE</strong> does nothing. Select+Back returns to <strong>SONG</strong>. Back <strong>leaves Arrange</strong> (it does not return to SONG) unless sticky edit is open, in which case Back restores first. Encoder click is Clock Start/Stop.</p><p>Changing <strong>Rate</strong> while the arrangement is running keeps the current song row and the time already spent on it. If the new rate is longer (or shorter but you have not used up the new length yet), the row continues from those ticks. If the new rate is shorter and you are already past it, the playhead waits for the <strong>next bar</strong>, then moves once. Arrange <strong>Fade Time</strong> is only how the <strong>playhead</strong> glides in — pad / MIDI / <strong>SNAPSHOT</strong> macro glides use each bank’s own <strong>FADE TIME</strong>. It does not move the playhead.</p><p><strong>Arrange</strong> (the first pencil-tab row) is whether the arrangement <strong>runs</strong>. <strong>ON</strong> (default) lets the playhead, Jump To, and Queue recall snapshots. <strong>OFF</strong> freezes the playhead and ignores Jump / Queue; the SONG grid stays editable. Select tap toggles ON/OFF. Turning the encoder while holding Select moves toward ON or OFF and stops at the end — it does not wrap. Old projects load as <strong>ON</strong>.</p><p><strong>Rate</strong> is how long each row lasts against the project clock (24 PPQN):</p><table tabindex="0"><thead><tr><th>Rate</th><th>MIDI clocks</th></tr></thead><tbody><tr><td><strong>1 BAR</strong> (default)</td><td>96</td></tr><tr><td><strong>2 BARS</strong> … <strong>128 BARS</strong></td><td>96 × bars, including 3, 5, 6, 7, …</td></tr></tbody></table><p>Old projects that stored <strong>1/8</strong> or <strong>1/4</strong> load as <strong>1 BAR</strong>. <strong>Start</strong> fires row 0 immediately at every Rate. Rate is how long until the <strong>next</strong> row. Transport Start resets the playhead; Continue keeps it.</p><p><strong>Fade Time</strong> is how a playhead recall <strong>arrives</strong> (musical time at project BPM). The musical-time choices are unchanged. Jump To and Queue stay instant.</p><table tabindex="0"><thead><tr><th>Fade Time</th><th>Beats (4/4)</th></tr></thead><tbody><tr><td><strong>OFF</strong> (default)</td><td>Instant</td></tr><tr><td><strong>1/16</strong></td><td>0.25</td></tr><tr><td><strong>1/8</strong></td><td>0.5</td></tr><tr><td><strong>1/4</strong></td><td>1</td></tr><tr><td><strong>1/2</strong></td><td>2</td></tr><tr><td><strong>1 BAR</strong></td><td>4</td></tr><tr><td><strong>2 BARS</strong></td><td>8</td></tr><tr><td><strong>4 BARS</strong></td><td>16</td></tr></tbody></table><p><strong>Repeat</strong> is <strong>LOOP</strong> (wrap after the last filled row inside the current length) or <strong>ONCE</strong> (play to that row and stop).</p><p><strong>Length</strong> is how many song rows are active (<strong>4–256</strong>, default <strong>16</strong>). Hold Select + encoder. Shrinking the song does not erase hidden rows — lengthen again and they are still there. Jump, Queue, and the playhead stay inside the current length.</p><p><strong>Jump To</strong> fires the focused song row <strong>now</strong> (instant — bypasses Fade Time) and cancels Queue. <strong>Queue</strong> arms or cancels that same row for the <strong>next Rate boundary</strong> (also instant versus a playhead fade). Both are a <strong>single Select tap</strong>. They do nothing while <strong>ARRANGE</strong> is <strong>OFF</strong>. Queue reads <strong>ARMED</strong> or <strong>OFF</strong>, never a second row number. While Queue is <strong>ARMED</strong>, that word <strong>pulses</strong> on the pencil tab (and the armed SONG row pulses). Jump To snaps an in-progress fade to its target; Queue cancels the fade without snapping. Queue still works after <strong>ONCE</strong> has already stopped.</p><p><img src="'+c+'" alt="Arrange SETTINGS" class="screen"></p><p>When a row fires:</p><ul><li><strong>Rest</strong> (<code>--</code>) or an empty slot — that column is skipped.</li><li>Occupied slot <strong>different</strong> from the one already active — recall that snapshot (playhead uses Fade Time; Jump To and Queue are instant). While a glide runs on that bank, “active” is the pad it is gliding to. Any other occupied pad turns the glide toward that pad, starting from the live sound. That includes the pad the glide is leaving.</li><li>Same slot as now — no second recall.</li><li>A <strong>MORPH</strong> knob turned up on that bank does not hold the column back. The step takes over like a pad recall, and the knob picks up from the new percent. It reads <strong>0%</strong> once the step lands.</li><li>Other columns in the row still fire.</li></ul><p>Arrange edits and recalls do <strong>not</strong> force a flash save. Use <a href="./../projects/">Save Project</a> so the pattern survives power-off.</p><p><img src="'+p+'" alt="Arrange hub" class="screen"></p><p>Hold Select for a moment (not a tap) on <strong>SONG</strong>: the header mark becomes a circle and square, and Gray8 L-corners mark the current column before you turn. Letting go then does not open the cell picker.</p><p><img src="'+u+'" alt="Arrange hold Select column" class="screen"></p>',20)),o(l,null,{default:h(()=>[...e[13]||(e[13]=[t("ul",null,[t("li",null,[t("a",{href:"./"},"Snapshots"),n(" — Snapshot overview")]),t("li",null,[t("a",{href:"./studio"},"Open a snapshot bank"),n(" — One door per bank")]),t("li",null,[t("a",{href:"./knob-bank"},"Knob snapshots"),n(" — 4×8 pad from Main Menu → Snapshots")]),t("li",null,[t("a",{href:"./rack-bank"},"Rack snapshots"),n(" — Live rack bank")]),t("li",null,[t("a",{href:"./lfo-bank"},"LFO snapshots"),n(" — Live LFO bank")]),t("li",null,[t("a",{href:"./morph"},"Morph"),n(" — Live to a pad; this bank's FADE TIME is the pad recall glide")]),t("li",null,[t("a",{href:"./../settings/"},"Settings"),n(" — Clock Settings (transport and BPM)")])],-1)])]),_:1})])}const R=d(m,[["render",b]]);export{E as __pageData,R as default};
